{
  "findings": [
    {
      "check_id": "CKV_AZURE_1",
      "title": "HTTPS traffic enforcement disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The 'enable_https_traffic_only' attribute is set to false, which allows unencrypted HTTP traffic. This can expose sensitive data to interception."
    },
    {
      "check_id": "CKV_AZURE_2",
      "title": "Insecure TLS version",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The 'min_tls_version' is set to 'TLS1_0', which is outdated and vulnerable to known attacks. A minimum of 'TLS1_2' is recommended for secure communication."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version = \"TLS1_2\"\n  blob_properties {\n    versioning_enabled = true\n  }\n}",
  "fix_summary": "Enabled HTTPS traffic enforcement by setting 'enable_https_traffic_only' to true and updated the minimum TLS version to 'TLS1_2' for secure communication."
}
